Assert-True ($attemptTemporaryEventFromTap -notmatch 'running_skill_id\s*=') "Temporary event card taps must not overwrite the active running skill."
Assert-True ($attemptTemporaryEventFromTap -notmatch 'running_action_id\s*=') "Temporary event card taps must not overwrite the active running action."
