Assert-True ($main -match 'const RoundedTextureRect = preload\("res://scripts/ui/rounded_texture_rect\.gd"\)') "Rounded card backgrounds should live in a reusable UI control file."
Assert-True ($roundedTexture -match 'static var shared_mask_shader: Shader') "Rounded card backgrounds should share one mask shader program."
Assert-True ($roundedTexture -match 'shader_material\.shader = shared_mask_shader') "Rounded card backgrounds should not allocate a unique Shader for every card."
Assert-True ($roundedTexture -match 'mask_shader_params_initialized') "Rounded card backgrounds should track the last synced shader parameters with shader-specific cache naming."
Assert-True ($roundedTexture -notmatch 'mask_params_initialized') "Rounded card backgrounds should not use vague mask-parameter cache names."
Assert-True ($roundedTexture -match 'texture = value if value != null else _fallback_texture\(\)') "Rounded card backgrounds should normalize null texture assignments to a fallback at the control boundary."
$roundedMaskParams = [regex]::Match($roundedTexture, "(?ms)^\s+func _update_mask_params\b.*?(?=^\s+func |\z)")
Assert-True $roundedMaskParams.Success "Could not find rounded card background mask-parameter updater."
Assert-True ($roundedMaskParams.Value -match 'var current_texture := _mask_texture\(\)') "Rounded card backgrounds should resolve the effective texture once before shader sync."
Assert-True ($roundedMaskParams.Value -match 'if current_texture == null:\s+return') "Rounded card backgrounds should skip shader sync if the fallback texture is unavailable during shutdown."
Assert-True ($roundedMaskParams.Value -match '_mask_shader_params_unchanged\(\)') "Rounded card backgrounds should skip repeated shader parameter writes."
Assert-True ($roundedMaskParams.Value.IndexOf('return') -lt $roundedMaskParams.Value.IndexOf('set_shader_parameter')) "Rounded card backgrounds should return before writing unchanged shader parameters."
Assert-True ($roundedMaskParams.Value -match 'var texture_changed := not mask_shader_params_initialized or mask_shader_params_texture != current_texture') "Rounded card backgrounds should detect sampler texture changes separately from other shader parameter changes."
Assert-True ($roundedMaskParams.Value -match 'if texture_changed:\s+shader_material\.set_shader_parameter\("bg_texture", current_texture\)') "Rounded card backgrounds should update the sampler only when the effective texture changes."
Assert-True ($roundedMaskParams.Value -match 'set_shader_parameter\("bg_texture", current_texture\)') "Rounded card backgrounds should never pass a nullable texture expression to the shader."
Assert-True ($roundedMaskParams.Value -notmatch 'texture if texture != null else _fallback_texture\(\)') "Rounded card backgrounds should keep nullable texture fallback ownership out of shader sync."
$roundedMaskTexture = [regex]::Match($roundedTexture, "(?ms)^\s+func _mask_texture\b.*?(?=^\s+func |\z)")
Assert-True $roundedMaskTexture.Success "Could not find rounded card background effective-texture helper."
Assert-True ($roundedMaskTexture.Value -match 'return texture if texture != null else _fallback_texture\(\)') "Rounded card backgrounds should share one effective texture helper for initial null state."
$roundedStoreMaskParams = [regex]::Match($roundedTexture, "(?ms)^\s+func _store_mask_shader_params\b.*?(?=^\s+func |\z)")
